function toggleChildren(parentId) {
  const parent = graphData.nodes.find(n => n.id === parentId);
  if (!parent) return;

  if (parent.expanded) {
    // Collapse: remove children
    const childIds = new Set(getChildIds(parentId));
    graphData.nodes = graphData.nodes.filter(n => !childIds.has(n.id));
    graphData.links = graphData.links.filter(l =>
      !childIds.has(l.source.id) && !childIds.has(l.target.id)
    );
    parent.expanded = false;
  } else {
    // Expand: add children
    const children = fetchChildren(parentId);
    graphData.nodes.push(...children);
    graphData.links.push(...children.map(c => ({
      source: parentId, target: c.id
    })));
    parent.expanded = true;
  }

  graph.graphData(graphData);
}

graph.onNodeClick(toggleChildren);

