import { EffectComposer } from 'three/examples/jsm/postprocessing/EffectComposer.js';
import { RenderPass } from 'three/examples/jsm/postprocessing/RenderPass.js';
import { UnrealBloomPass } from 'three/examples/jsm/postprocessing/UnrealBloomPass.js';
import * as THREE from 'three';

const composer = graph.postProcessingComposer();

const bloomPass = new UnrealBloomPass(
  new THREE.Vector2(window.innerWidth, window.innerHeight),
  1.5,   // bloom strength
  0.4,   // radius
  0.85   // luminance threshold
);
composer.addPass(bloomPass);

// Make nodes glow by increasing emissive:
graph.nodeThreeObject(node => {
  const geo = new THREE.SphereGeometry(node.val * 2);
  const mat = new THREE.MeshStandardMaterial({
    color: node.color,
    emissive: node.color,
    emissiveIntensity: 0.8
  });
  return new THREE.Mesh(geo, mat);
});

const dims = { nodes: 0.1, links: 0.05 };
const normal = { nodes: 0.75, links: 0.2 };

graph.onNodeHover(node => {
  if (!node) {
    graph.nodeOpacity(normal.nodes).linkOpacity(normal.links);
    return;
  }

  const connectedIds = new Set();
  graph.graphData().links.forEach(l => {
    const src = l.source.id || l.source;
    const tgt = l.target.id || l.target;
    if (src === node.id || tgt === node.id) {
      connectedIds.add(src).add(tgt);
    }
  });

  graph.nodeOpacity(n =>
    n.id === node.id || connectedIds.has(n.id) ? 1 : dims.nodes
  ).linkOpacity(l => {
    const src = l.source.id || l.source;
    const tgt = l.target.id || l.target;
    return (src === node.id || tgt === node.id) ? 0.8 : dims.links;
  });
});

let graphData = { nodes: [], links: [] };
const ws = new WebSocket('wss://stream.example.com/graph');

ws.onmessage = ({ data }) => {
  const update = JSON.parse(data);

  switch (update.type) {
    case 'node_added':
      graphData.nodes.push(update.node);
      break;
    case 'node_removed':
      graphData.nodes = graphData.nodes.filter(n => n.id !== update.id);
      graphData.links = graphData.links.filter(l =>
        (l.source.id || l.source) !== update.id &&
        (l.target.id || l.target) !== update.id
      );
      break;
    case 'link_added':
      graphData.links.push(update.link);
      break;
    case 'bulk_sync':
      graphData = update.data;
      break;
  }

  graph.graphData(graphData);
};

