import * as THREE from 'three';

graph.linkMaterial(link => {
  const src = link.source;
  const tgt = link.target;

  const canvas = document.createElement('canvas');
  canvas.width = 256;
  canvas.height = 1;
  const ctx = canvas.getContext('2d');
  const gradient = ctx.createLinearGradient(0, 0, 256, 0);
  gradient.addColorStop(0, src.color || '#ff0000');
  gradient.addColorStop(1, tgt.color || '#0000ff');
  ctx.fillStyle = gradient;
  ctx.fillRect(0, 0, 256, 1);

  const texture = new THREE.CanvasTexture(canvas);
  return new THREE.MeshBasicMaterial({
    map: texture,
    transparent: true,
    opacity: 0.8
  });
});

// Or with MeshStandardMaterial for lighting:
graph.linkThreeObject(link => {
  const curve = new THREE.LineCurve3(
    new THREE.Vector3(link.source.x, link.source.y, link.source.z),
    new THREE.Vector3(link.target.x, link.target.y, link.target.z)
  );
  const geo = new THREE.TubeGeometry(curve, 20, 0.5, 8, false);
  const mat = new THREE.MeshStandardMaterial({
    color: link.color || '#888',
    metalness: 0.5,
    roughness: 0.3
  });
  return new THREE.Mesh(geo, mat);
});

