import { useEffect, useRef, useState, useCallback } from 'react';
import ForceGraph3D from 'three-forcegraph';
import * as THREE from 'three';

export default function GraphViewer({ initialData }) {
  const containerRef = useRef(null);
  const graphRef = useRef(null);
  const [selected, setSelected] = useState(null);
  const [dims, setDims] = useState({
    width: window.innerWidth,
    height: window.innerHeight
  });

  // Handle window resize
  useEffect(() => {
    const handle = () => setDims({
      width: window.innerWidth,
      height: window.innerHeight
    });
    window.addEventListener('resize', handle);
    return () => window.removeEventListener('resize', handle);
  }, []);

  // Initialize graph
  useEffect(() => {
    if (!containerRef.current) return;

    const graph = ForceGraph3D({ three: THREE, width: dims.width, height: dims.height })(
      containerRef.current
    );
    graphRef.current = graph;

    graph
      .backgroundColor('#0d1117')
      .nodeAutoColorBy('group')
      .nodeLabel(d => d.name || d.id)
      .onNodeClick(setSelected);

    if (initialData) graph.graphData(initialData);

    return () => graph._destructor();
  }, [dims]);

  return (
    <div style={{ position: 'relative' }}>
      <div ref={containerRef} />
      {selected && (
        <NodePanel node={selected} onClose={() => setSelected(null)} />
      )}
    </div>
  );
}

