const toGraphData = (adjList) => {
  const nodes = Object.keys(adjList).map(id => ({ id }));
  const links = [];
  Object.entries(adjList).forEach(([source, targets]) => {
    targets.forEach(target => {
      links.push({ source, target });
    });
  });
  return { nodes, links };
};

const csvToGraphData = (rows) => {
  const nodes = [], links = [], seen = {};
  rows.forEach(({ size, path }) => {
    nodes.push({ id: path, size: +size || 0, path });
    const parts = path.split('/');
    if (parts.length > 1) {
      const parent = parts.slice(0, -1).join('/');
      links.push({ source: parent || 'd3', target: path });
    }
  });
  return { nodes, links };
};

const edgesToGraphData = (edges) => {
  const nodeMap = {};
  edges.forEach(({ source, target }) => {
    nodeMap[source] = true;
    nodeMap[target] = true;
  });
  return {
    nodes: Object.keys(nodeMap).map(id => ({ id })),
    links: edges
  };
};

